def transform(grid):
    h, w = len(grid), len(grid[0])

    full_line_colors = []
    for row in grid:
        if all(x == row[0] for x in row):
            full_line_colors.append(row[0])
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            full_line_colors.append(grid[0][c])

    sep = max(set(full_line_colors), key=full_line_colors.count)
    sep_rows = [r for r in range(h) if all(x == sep for x in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]

    row_ranges = []
    start = 0
    for r in sep_rows:
        if start < r:
            row_ranges.append((start, r))
        start = r + 1
    if start < h:
        row_ranges.append((start, h))

    col_ranges = []
    start = 0
    for c in sep_cols:
        if start < c:
            col_ranges.append((start, c))
        start = c + 1
    if start < w:
        col_ranges.append((start, w))

    excluded = set(sep_rows)
    excluded_cols = set(sep_cols)
    counts = {}
    for r in range(h):
        if r in excluded:
            continue
        for c in range(w):
            if c not in excluded_cols:
                v = grid[r][c]
                counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    out = []
    for r0, r1 in row_ranges:
        row = []
        for c0, c1 in col_ranges:
            marks = sum(
                grid[r][c] != background
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            row.append(1 if marks == 2 else background)
        out.append(row)
    return out
